        return [row[:] for row in grid]
    minr = min(r for r, c in eight)
    minc = min(c for r, c in eight)
    target = None
    chosen_k = None
    for k in range(1, min(h, w) + 1):
        blocks = set()
        covered = 0
        for r in range(minr, h - k + 1, k):
            for c in range(minc, w - k + 1, k):
                if all(grid[rr][cc] == 8 for rr in range(r, r+k) for cc in range(c, c+k)):
                    blocks.add(((r-minr)//k, (c-minc)//k))
                    covered += k*k
        if covered == len(eight) and len(blocks) == len(clue):
            chosen_k, target = k, blocks
            break
    if target is None:
        return [row[:] for row in grid]
    points = list(clue)
    out = [row[:] for row in grid]
    for turns in range(4):
        for reflect in (False, True):
            mapped = {}
            for (r, c), color in clue.items():
                x, y = c, r
                for _ in range(turns):
                    x, y = y, -x
                if reflect:
                    x = -x
                mapped[(y, x)] = color
            miny = min(y for y, x in mapped)
            minx = min(x for y, x in mapped)
            normalized = {(y-miny, x-minx): color for (y, x), color in mapped.items()}
            if set(normalized) == target:
                for (br, bc), color in normalized.items():
                    r0, c0 = minr + br*chosen_k, minc + bc*chosen_k
                    for r in range(r0, r0+chosen_k):
                        for c in range(c0, c0+chosen_k):
                            out[r][c] = color
                return out
    return out
